#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    vector<long long> row = {1};
    for (int k = 0; k < n; k++) {
        for (size_t i = 0; i < row.size(); i++) cout << row[i] << (i + 1 < row.size() ? " " : "\n");
        vector<long long> next(row.size() + 1, 1);
        for (size_t i = 1; i < row.size(); i++) next[i] = row[i - 1] + row[i];
        row = next;
    }

    return 0;
}

